CREATE Proc [dbo].[ReportInvoiceVendorWiseReport] @InvoiceNo as nvarchar(max), @Login as nvarchar(max) as select  @Login as LoginUser,im.Date,v.Vendor,s.Store,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType, iu.PkFactor as UnitQty,im.InvoiceNo, (Select Distinct(Unit) from unit  where UId=idc.Unit) as UnitType, (select ParLevel from ItemParLevel where ItemId= i.ItemId and SId = s.SId) as ParLevel, isnull([dbo].funcGetItemAvgRateInvoice(im.InvoiceId,i.ItemId,U.UId),0) as UnitPrice, idc.Qty as PurchaseQty  from InvoiceMaster_CompanyNew im  inner join InvoiceDetail_CompanyNew idc on im.InvoiceId=idc.InvoiceId inner join Vendor v on v.VId=im.VId inner join Store s on im.SId=s.SId inner join Item i on idc.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join Split(@InvoiceNo,',') sp on sp.items = im.InvoiceId group by im.Date,v.Vendor,s.Store,c.Category,sc.Subcategory,i.Item, U.Unit,iu.PkFactor,im.InvoiceNo,idc.Unit, im.InvoiceId,i.ItemId,U.UId,idc.Qty ,s.SId order by im.date asc